meta.script:
jQuery(function($){
	var buttons = {
		'.rv_button_1': {
			'hide'  : '.rv_element_2',
			'show': '.rv_element_1', 
			//'show'  : '.show-on-click'
		},
		'.rv_button_2': {
			'hide'  : '.rv_element_1',
			'show': '.rv_element_2', 
			//'show'  : '.show-on-click'
		}
	};
	$.each(buttons, function(button, elements) {
		$(button).click(function(e){
			e.preventDefault();
			
			// Schließe alle anderen Buttons
            $.each(buttons, function(otherButton) {
                if(otherButton !== button) {
                    $(otherButton).addClass('rv_button_closed').removeClass('rv_button_opened');
                }
            });
			
			$(elements.toggle).slideToggle();
			$(elements.hide).fadeOut();
			$(elements.show).fadeIn();
			//$(button).addClass('rv_button_closed').removeClass('rv_button_opened');
			$(button).toggleClass('rv_button_opened rv_button_closed');
		});
	});
});

jQuery(function($){
	
	setTimeout(function(){
	
		// Get the timers
		var timers = $('.et_pb_countdown_timer');
		
		timers.each(function(){
			
			var timer = $(this);
			
			// Get the label objects
			var days = timer.find('.days');
			var hours = timer.find('.hours');
			var mins = timer.find('.minutes');
			var secs = timer.find('.seconds');
			
			// Change labels on desktop
			days.data('full', 'Days');
			hours.data('full', 'Hours');
			mins.data('full', 'Minutes');
			secs.data('full', 'Seconds');
			
			// Change labels on mobile
			days.data('short', 'Day');
			hours.data('short', 'Hrs');
			mins.data('short', 'Min');
			secs.data('short', 'Sec');
			
			// Apply changes
			window.et_countdown_timer_labels(timer);
		});
		
	}, 0);
	
});

jQuery(function($){
var olddays = $('.et_pb_countdown_timer .days .value');
// Clone the days and hide the original.
// - Wraps new days element in a span to prevent Divi from updating it
olddays.each(function(){
var oldday = $(this);
oldday.after(oldday.clone());
oldday.next().wrap('');
}).hide();
// Update the clone each second, removing the trailing zero
(function update_days() {
olddays.each(function(){
var oldday = $(this);
var days = oldday.html();
if (days.substr(0,1) == '0') { days = days.slice(1); }
oldday.next().find('.value').html(days);
});
setTimeout(function(){ update_days(); }, 100);
})()
});

